      .references(() => pilotApplications.id, { onDelete: 'cascade' })
      .notNull(),
    organizationId: uuid('organization_id')
      .references(() => organizations.id, { onDelete: 'cascade' })
      .notNull(),
    enrollmentDate: timestamp('enrollment_date').notNull(),
